Hub.ApplyPotatoOptimizer = function(self, enabled)
	local lighting = self.Services.Lighting;
	if not self.State.PotatoBackup then
		self.State.PotatoBackup = {};
	end
	if enabled then
		if not self.State.PotatoLightingBackup then
			self.State.PotatoLightingBackup = {GlobalShadows=lighting.GlobalShadows,FogEnd=lighting.FogEnd,Brightness=lighting.Brightness};
		end
		pcall(function()
			lighting.GlobalShadows = false;
			lighting.FogEnd = 8999999488;
			lighting.Brightness = 2;
		end);
		for _, obj in ipairs(self.Services.Workspace:GetDescendants()) do
			self:OptimizeInstance(obj);
		end
		if not self.State.OptimizerConn then
			self.State.OptimizerConn = self.Services.Workspace.DescendantAdded:Connect(function(obj)
				if self.Config.Toggles.PotatoOptimizer then
					self:OptimizeInstance(obj);
				end
			end);
		end
	else
		if self.State.PotatoLightingBackup then
			pcall(function()
				lighting.GlobalShadows = self.State.PotatoLightingBackup.GlobalShadows;
				lighting.FogEnd = self.State.PotatoLightingBackup.FogEnd;
				lighting.Brightness = self.State.PotatoLightingBackup.Brightness;
			end);
			self.State.PotatoLightingBackup = nil;
		else
			pcall(function()
				lighting.GlobalShadows = self.Config.Toggles.WorldShadows;
				lighting.FogEnd = (self.Config.Toggles.NoFog and 8999999488) or 500;
			end);
		end
		if self.State.OptimizerConn then
			self.State.OptimizerConn:Disconnect();
			self.State.OptimizerConn = nil;
		end
		for obj, data in pairs(self.State.PotatoBackup) do
			if (obj and obj.Parent) then
				pcall(function()
					if (data.Type == "BasePart") then
						obj.Material = data.Material;
						obj.CastShadow = data.CastShadow;
						obj.Reflectance = data.Reflectance;
						if (data.TextureID and obj:IsA("MeshPart")) then
							obj.TextureID = data.TextureID;
						end
					elseif (data.Type == "Decal") then
						obj.Transparency = data.Transparency;
					elseif (data.Type == "SpecialMesh") then
						obj.TextureId = data.TextureId;
					elseif (data.Type == "Toggleable") then
						obj.Enabled = data.Enabled;
					end
				end);
			end
		end
		table.clear(self.State.PotatoBackup);
	end
end;
Hub.OptimizeInstance = function(self, obj)
	pcall(function()
		if not self.State.PotatoBackup then
			self.State.PotatoBackup = {};
		end
		if obj:IsA("BasePart") then
			local isPlayerChar = obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid");
			if not isPlayerChar then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {Type="BasePart",[LUAOBFUSACTOR_DECRYPT_STR_0("\205\9\82\36\193\179\212\220", "\176\128\104\38\65\179\218\181")]=obj.Material,[LUAOBFUSACTOR_DECRYPT_STR_0("\243\197\209\1\227\204\195\17\223\211", "\117\176\164\162")]=obj.CastShadow,Reflectance=obj.Reflectance,[LUAOBFUSACTOR_DECRYPT_STR_0("\176\199\29\228\207\107\129\235\33", "\25\228\162\101\144\186")]=((obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\101\51\170\6\194\229\90\34", "\132\40\86\217\110\146")) and obj.TextureID) or nil)};
				end
				obj.Material = Enum.Material.SmoothPlastic;
				obj.CastShadow = false;
				obj.Reflectance = 0;
				if obj:IsA("MeshPart") then
					local nm = obj.Name:lower();
					local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
					if (nm:find("coin") or pnm:find("coin")) then
						obj.TextureID = "";
					end
				end
			end
		elseif obj:IsA("SpecialMesh") then
			local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
			local ppnm = (obj.Parent and obj.Parent.Parent and obj.Parent.Parent.Name:lower()) or "";
			if (pnm:find(LUAOBFUSACTOR_DECRYPT_STR_0("\125\196\46\178", "\62\30\171\71\220\199\19\156")) or ppnm:find("coin")) then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {Type="SpecialMesh",TextureId=obj.TextureId};
				end
				obj.TextureId = "";
			end
		elseif (obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\100\64\175\55\81", "\45\32\37\204\86\61\169\79")) or obj:IsA("Texture")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Decal",[LUAOBFUSACTOR_DECRYPT_STR_0("\97\71\4\178\166\108\84\71\0\178\182\101", "\28\53\53\101\220\213")]=obj.Transparency};
			end
			obj.Transparency = 1;
		elseif (obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") or obj:IsA("Light")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {[LUAOBFUSACTOR_DECRYPT_STR_0("\57\69\24\68", "\191\109\60\104\33\58\193\48")]=LUAOBFUSACTOR_DECRYPT_STR_0("\179\216\31\224\139\210\25\229\139\210", "\135\231\183\120"),Enabled=obj.Enabled};
			end
			obj.Enabled = false;
		end
	end);
end;
Hub.SetFarmNoClip = function(self, on)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if on then
		if not char then
			return;
		end
		if hum then
			pcall(function()
				hum.PlatformStand = true;
			end);
		end
		for _, p in ipairs(char:GetDescendants()) do
			if (p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\196\11\95\225\5\27\187\242", "\201\134\106\44\132\85\122")) and p.CanCollide) then
				if (self.AutoFarm.NoClipCache[p] == nil) then
					self.AutoFarm.NoClipCache[p] = p.CanCollide;
				end
				p.CanCollide = false;
			end
		end
	else
		if hum then
			hum.PlatformStand = false;
			hum.Sit = false;
			hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
			hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
			hum:ChangeState(Enum.HumanoidStateType.GettingUp);
			task.defer(function()
				if (hum and not self.AutoFarm.IsActive) then
					hum:ChangeState(Enum.HumanoidStateType.Running);
				end
			end);
		end
		if not self.Config.Toggles.NoClip then
			for p, v in pairs(self.AutoFarm.NoClipCache or {}) do
				if (p and p.Parent) then
					pcall(function()
						p.CanCollide = v;
					end);
				end
			end
			if char then
				for _, p in ipairs(char:GetDescendants()) do
					if p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\20\13\100\58\49\13\218\55", "\67\86\108\23\95\97\108\168")) then
						if (p.Name == "HumanoidRootPart") then
							p.CanCollide = false;
						elseif ((p.Name == "Head") or p.Name:find("Torso") or p.Name:find("Leg") or p.Name:find("Arm")) then
							p.CanCollide = true;
						end
					end
				end
			end
		end
		self.AutoFarm.NoClipCache = {};
	end
end;
Hub.ReturnToSurface = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if not root then
		return;
	end
	local upParams = RaycastParams.new();
	upParams.FilterType = Enum.RaycastFilterType.Exclude;
	upParams.IgnoreWater = true;
	upParams.FilterDescendantsInstances = {char};
	local res = self.Services.Workspace:Raycast(root.Position, Vector3.new(0, 400, 0), upParams);
	local y = (res and (res.Position.Y + 4)) or (self.AutoFarm.DownRefY and (self.AutoFarm.DownRefY + 4)) or (root.Position.Y + 16);
	pcall(function()
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
Hub.ReleaseFarm = function(self)
	self.AutoFarm.HoldCF = nil;
	if self.AutoFarm.WasDown then
		self.AutoFarm.WasDown = false;
		self:ReturnToSurface();
	end
	self:SetFarmNoClip(false);
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if root then
		local _, ry, _ = root.CFrame:ToOrientation();
		root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, ry, 0);
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end
	if hum then
		hum.PlatformStand = false;
		hum.Sit = false;
		hum:SetStateEnabled(Enum.HumanoidStateType.Running, true);
		hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true);
		hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		task.defer(function()
			if (hum and not self.AutoFarm.IsActive) then
				hum:ChangeState(Enum.HumanoidStateType.Running);
			end
		end);
	end
end;
Hub.StopAutoFarm = function(self)
	self.AutoFarm.Target = nil;
	if self.AutoFarm.IsActive then
		self.AutoFarm.IsActive = false;
	end
	self:ReleaseFarm();
end;
Hub.StopAutoFarmTween = function(self)
	self:StopAutoFarm();
end;
Hub.IsCoinBagFull = function(self)
	local isFull = false;
	local limit = self.Config.Values.AutoFarmBagLimit or 50;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild("PlayerGui");
		local mg = pgui and pgui:FindFirstChild("MainGUI");
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild("Game") and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA("Frame") and bagFrame.Visible) then
					local fullLabel = bagFrame:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\130\45\64\6", "\48\196\88\44\106\196\68\181"));
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
					for _, lbl in ipairs(bagFrame:GetDescendants()) do
						if (lbl:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\182\218\196\55\172\165\160\41\142", "\76\226\191\188\67\224\196\194")) and lbl.Visible) then
							local txt = lbl.Text:match("(%d+)");
							if txt then
								local num = tonumber(txt);
								if (num and (num >= limit)) then
									isFull = true;
									return;
								end
							end
						end
					end
				end
			end
		end
		local scriptFolder = coinBags:FindFirstChild("CoinBagContainerScript");
		local fullNotif = scriptFolder and scriptFolder:FindFirstChild("FullBagNotification");
		if (fullNotif and fullNotif.Visible) then
			isFull = true;
			return;
		end
	end);
	return isFull;
end;
Hub.GetAvailableCoins = function(self)
	local list = {};
	local cs = self.Services.CollectionService;
	local ok, tagged = pcall(function()
		return cs:GetTagged("CoinVisual");
	end);
	if (ok and (type(tagged) == LUAOBFUSACTOR_DECRYPT_STR_0("\205\41\5\252\248", "\157\185\72\103\144")) and (#tagged > 0)) then
		for _, v in ipairs(tagged) do
			if (v and v.Parent and v:IsA("BasePart")) then
				if (not v:GetAttribute("Collected") and not v:GetAttribute("Delete")) then
					table.insert(list, v);
				end
			end
		end
	end
	if (#list == 0) then
		local coinContainer = self.Services.Workspace:FindFirstChild("CoinContainer", true);
		if coinContainer then
			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA("BasePart") and c.Parent and not c:GetAttribute("Collected")) then
					table.insert(list, c);
				elseif (c:IsA("Model") and c.Parent) then
					local p = c.PrimaryPart or c:FindFirstChildWhichIsA("BasePart");
					if (p and not p:GetAttribute(LUAOBFUSACTOR_DECRYPT_STR_0("\122\188\134\118\173\178\77\182\142", "\209\57\211\234\26\200"))) then
						table.insert(list, p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\35\207\181\132\96\211\19\218", "\178\97\174\198\225\48")) and p:FindFirstChildOfClass("TouchTransmitter")) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
