	local pg = lp and lp:FindFirstChild("PlayerGui");
	if not pg then
		return nil, nil;
	end
	local mainGui = pg:FindFirstChild("MainGUI");
	local gameGui = mainGui and mainGui:FindFirstChild("Game");
	local inv = (gameGui and gameGui:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\113\32\232\247\86\58\241\224\65", "\146\56\78\158"))) or pg:FindFirstChild("Inventory", true);
	if (not inv or not inv.Visible) then
		return nil, nil;
	end
	local weapons = inv:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\0\218\70\232", "\58\77\187\47\134")) and inv.Main:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\37\48\160\23\234\32\71", "\126\114\85\193\103\133\78\52"));
	if (not weapons or not weapons.Visible) then
		return inv, nil;
	end
	local items = weapons:FindFirstChild("Items");
	local contWrapper = items and items:FindFirstChild("Container");
	return inv, contWrapper;
end;
Hub.FindTradeGui = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local pg = lp and lp:FindFirstChild("PlayerGui");
	if not pg then
		return nil;
	end
	local mainGui = pg:FindFirstChild("MainGUI");
	local tradeGui = pg:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\240\201\51\124\193\252\7\81", "\24\164\187\82")) or (mainGui and mainGui:FindFirstChild("Trade", true));
	if not tradeGui then
		return nil;
	end
	local isOpen = false;
	if tradeGui:IsA("ScreenGui") then
		isOpen = tradeGui.Enabled;
	elseif tradeGui:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\214\207\85\133\243\251\223\95\190", "\145\145\186\60\202")) then
		isOpen = tradeGui.Visible;
		local cur = tradeGui.Parent;
		while cur and cur:IsA("GuiObject") do
			if not cur.Visible then
				isOpen = false;
				break;
			end
			cur = cur.Parent;
		end
	end
	if not isOpen then
		return nil;
	end
	return tradeGui;
end;
Hub.CleanInventoryBadges = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local pg = lp and lp:FindFirstChild("PlayerGui");
	if not pg then
		return;
	end
	for _, desc in ipairs(pg:GetDescendants()) do
		if ((desc.Name == "ValueBadge") or (desc.Name == "MM2TotalValueHeader") or (desc.Name == "TotalValHeader")) then
			pcall(function()
				desc:Destroy();
			end);
		end
	end
end;
