	local yourOffer = trade:FindFirstChild("YourOffer", true) or trade:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\225\2\233\94\230\161\80", "\34\172\123\166\56\128\196"), true);
	local theirOffer = trade:FindFirstChild("TheirOffer", true) or trade:FindFirstChild("OtherOffer", true);
	local function processOffer(offer)
