			if (#slots == 0) then
				for _, ch in ipairs(cont:GetChildren()) do
					if (ch:IsA("GuiObject") and not ch:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\67\175\215\92\12\15\9\98", "\124\22\230\155\61\117\96")) and (ch.Name ~= LUAOBFUSACTOR_DECRYPT_STR_0("\243\170\234\254\251\207\244\193\172\227", "\149\165\203\134\139\158\141")) and (ch.Name ~= "SV_Value")) then
						slots[#slots + 1] = ch;
					end
				end
			end
		end
		if (#slots == 0) then
			for _, ch in ipairs(offer:GetChildren()) do
				if (ch:IsA("GuiObject") and not ch:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\6\133\108\39\42\163\85\50", "\70\83\204\32")) and (ch.Name ~= LUAOBFUSACTOR_DECRYPT_STR_0("\45\142\5\148\15\136\5\133\28", "\224\110\225\107")) and (ch.Name ~= LUAOBFUSACTOR_DECRYPT_STR_0("\192\127\201\61\53", "\164\148\22\189\81\80\164")) and (ch.Name ~= "Username") and (ch.Name ~= "ValueBadge") and (ch.Name ~= LUAOBFUSACTOR_DECRYPT_STR_0("\129\182\72\135\40\95\118\190", "\23\210\224\23\211\71\43"))) then
					slots[#slots + 1] = ch;
				end
