				if (itemName and (itemName ~= "") and (itemName ~= "Loading...") and (itemName ~= "...")) then
					local inner = slot:FindFirstChild("Container");
					local amtLbl = (inner and inner:FindFirstChild("Amount")) or slot:FindFirstChild("Amount");
