	panel.Visible = true;
	local yLabel = panel:FindFirstChild("YourValLabel");
	local vLabel = panel:FindFirstChild("VerdictLabel");
	local tLabel = panel:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\28\48\31\66\159\15\41\52\54\74\143\60\36", "\89\72\88\122\43\237"));
